def _release_interrupted_claim(state, deps, claim=None):
    """Release work claimed by a tick that failed before it became durable.

    Dispatch claims are written before the lap state is persisted. If starting
    the lap or saving state fails, remove the claim and stop any child that
    may have been started so the next tick can retry the issue.
    """
    lap = state.get("lap") or {}
    claim = claim or {}
    path = lap.get("claim_path") or claim.get("path")
    if not path:
        return False
    issue = lap.get("issue", claim.get("issue"))
    kill = deps.get("kill_lap")
    if kill and lap:
        try:
            kill(lap)
        except Exception:
            pass
    try:
        os.remove(path)
    except OSError:
        pass
    state["lap"] = None
    try:
        runtime_log("intervention", issue=issue,
                    detail="interrupted dispatch claim released: %s" % path)
    except Exception:
        pass
    state_path = deps.get("state_path")
    if state_path:
        try:
            save_state(state, state_path)
        except Exception:
            pass
    return True


def dispatch(state, now, deps):

try:
    # L-013: never spend a lap on an already-satisfied issue. Re-prove the
    # repro is RED on fresh main first; GREEN → reconcile as merged + skip.
    recheck = deps.get("red_recheck")
    if recheck:
        verdict = recheck(claim["issue"])
        runtime_log("red-recheck", issue=claim["issue"], verdict=verdict)
        if verdict == "pass":
            state.setdefault("issues", {}).setdefault(str(claim["issue"]), {"retries": 0})
            state["issues"][str(claim["issue"])] ["disposition"] = "merged"
            try:
                os.remove(claim["path"])
            except OSError:
                pass
            save_state(state, deps["state_path"])
            return "already-satisfied"
except Exception:
    _release_interrupted_claim(state, deps, claim)
    raise
